const CONFIG = $('2. Load CONFIG').first().json.config;
const ABBR = CONFIG.title_abbreviations;
const EMAIL_RE = /^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/;

function clean(s){ return String(s == null ? "" : s).replace(/\s+/g, " ").trim(); }
function titleCase(s){ return clean(s).toLowerCase().replace(/(^|[\s\-'])([a-z])/g, function(m, a, b){ return a + b.toUpperCase(); }); }
function normPhone(p){
  let d = String(p || "").replace(/[^\d+]/g, "");
  if (!d) return "";
  if (d.indexOf("00") === 0) d = "+" + d.slice(2);
  if (d.charAt(0) === "0") d = "+44" + d.slice(1);
  if (d.charAt(0) !== "+") d = "+" + d;
  return d;
}
function normTitle(t){
  return clean(t).split(" ").map(function(w){
    const k = w.toLowerCase().replace(/[.,]/g, "");
    return ABBR[k] ? ABBR[k] : w;
  }).join(" ");
}
function normDate(d){ const t = new Date(d); return isNaN(t.getTime()) ? "" : t.toISOString(); }
function numOrNull(v){ if (v === "" || v === null || v === undefined) return null; const n = Number(v); return isNaN(n) ? null : n; }

return $input.all().map(function(item){
  const j = item.json;
  if (j.halt) return item;
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];

  const full_name = titleCase(j.full_name);
  const parts = full_name.split(" ");
  const email = clean(j.email).toLowerCase();
  const email_valid = EMAIL_RE.test(email);
  const phone = normPhone(j.phone);
  const digits = phone.replace(/\D/g, "");

  if (!full_name) reasons.push("MISSING_NAME");
  if (!email) reasons.push("MISSING_EMAIL"); else if (!email_valid) reasons.push("INVALID_EMAIL");
  if (phone && (digits.length < 10 || digits.length > 15)) reasons.push("INVALID_PHONE");

  const basis = clean(j.processing_basis || "unknown").toLowerCase();
  if (["consent", "legitimate_interest", "contract"].indexOf(basis) === -1) reasons.push("PROCESSING_BASIS_UNCONFIRMED");

  const years = numOrNull(j.years_experience);
  if (years === null) reasons.push("MISSING_EXPERIENCE");
  if (!clean(j.skills_raw) && !clean(j.summary_text)) reasons.push("NO_SKILLS_OR_SUMMARY");

  const rec = {
    candidate_ref: clean(j.candidate_ref) || "UNKNOWN",
    full_name: full_name || "UNKNOWN",
    first_name: parts[0] || "",
    last_name: parts.slice(1).join(" "),
    email: email,
    email_valid: email_valid,
    phone: phone,
    location: titleCase(j.location) || "UNKNOWN",
    current_title: normTitle(j.current_title),
    years_experience: years === null ? null : Math.max(0, Math.min(50, years)),
    skills_raw: clean(j.skills_raw),
    summary_text: clean(j.summary_text),
    desired_salary: numOrNull(j.desired_salary),
    notice_period_weeks: numOrNull(j.notice_period_weeks),
    work_mode_pref: clean(j.work_mode_pref).toLowerCase() || "unknown",
    relocate: Boolean(j.relocate),
    applied_at: normDate(j.applied_at),
    source: clean(j.source) || "UNKNOWN",
    processing_basis: basis,
    data_label: j.data_label,
    run_mode: j.run_mode,
    workflow_version: j.workflow_version,
    received_at: j.received_at,
    status: reasons.length ? "REQUIRES_REVIEW" : "OK",
    review_reasons: reasons
  };
  return { json: rec };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const items = $input.all();
const halted = items.filter(function(i){ return i.json.halt; });
if (halted.length && halted.length === items.length) return items;

function richness(j){
  return (j.skills_raw || "").length + (j.summary_text || "").length + (j.email_valid ? 50 : 0) + (j.phone ? 20 : 0) + (j.years_experience !== null ? 10 : 0);
}
function keysOf(j){
  const k = [];
  if (j.email_valid) k.push("e:" + j.email);
  if (j.phone) k.push("p:" + j.phone);
  if (j.full_name !== "UNKNOWN" && j.location !== "UNKNOWN") k.push("n:" + j.full_name.toLowerCase() + "|" + j.location.toLowerCase());
  return k;
}

const groups = [];
const keyToGroup = {};
let rawCount = 0;

items.filter(function(i){ return !i.json.halt; }).forEach(function(i){
  rawCount++;
  const rec = JSON.parse(JSON.stringify(i.json));
  const ks = keysOf(rec);
  let gi = -1;
  for (const k of ks) { if (keyToGroup[k] !== undefined) { gi = keyToGroup[k]; break; } }
  if (gi === -1) {
    gi = groups.length;
    rec.merged_refs = [rec.candidate_ref];
    rec.application_count = 1;
    rec.alt_emails = [];
    rec.duplicates_merged = 0;
    groups.push(rec);
  } else {
    let base = groups[gi];
    let other = rec;
    if (richness(other) > richness(base)) {
      const carry = { merged_refs: base.merged_refs, application_count: base.application_count, alt_emails: base.alt_emails, duplicates_merged: base.duplicates_merged };
      const swapped = Object.assign({}, other, carry);
      swapped.alt_emails = swapped.alt_emails.slice();
      if (base.email && base.email !== swapped.email && swapped.alt_emails.indexOf(base.email) === -1) swapped.alt_emails.push(base.email);
      const oldBase = base;
      base = swapped; other = oldBase;
      groups[gi] = base;
    } else if (other.email && other.email !== base.email && base.alt_emails.indexOf(other.email) === -1) {
      base.alt_emails.push(other.email);
    }
    ["email","phone","current_title","skills_raw","summary_text","location"].forEach(function(f){
      if ((!base[f] || base[f] === "UNKNOWN") && other[f]) base[f] = other[f];
    });
    ["years_experience","desired_salary","notice_period_weeks"].forEach(function(f){
      if (base[f] === null && other[f] !== null) base[f] = other[f];
    });
    base.email_valid = /^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/.test(base.email || "");
    if (other.applied_at && (!base.applied_at || other.applied_at < base.applied_at)) base.applied_at = other.applied_at;
    base.merged_refs = base.merged_refs.concat(other.merged_refs || [other.candidate_ref]).filter(function(v, idx, a){ return a.indexOf(v) === idx; });
    base.application_count += 1;
    base.duplicates_merged += 1;
    const kept = (base.review_reasons || []).filter(function(r){ return ["MISSING_EMAIL","INVALID_EMAIL"].indexOf(r) === -1; });
    const others = (other.review_reasons || []).filter(function(r){ return ["MISSING_EMAIL","INVALID_EMAIL","MISSING_NAME"].indexOf(r) === -1 && kept.indexOf(r) === -1; });
    base.review_reasons = kept.concat(others);
    if (!base.email) base.review_reasons.push("MISSING_EMAIL"); else if (!base.email_valid) base.review_reasons.push("INVALID_EMAIL");
    base.status = base.review_reasons.length ? "REQUIRES_REVIEW" : "OK";
  }
  keysOf(groups[gi]).concat(ks).forEach(function(k){ keyToGroup[k] = gi; });
});

const existing = CONFIG.simulated_existing_records || [];
const minDays = CONFIG.comms.min_days_between_touches;

return groups.map(function(g){
  const emails = [g.email].concat(g.alt_emails).filter(Boolean);
  const hit = existing.filter(function(e){ return emails.indexOf(String(e.email).toLowerCase()) !== -1; })[0];
  g.crm_match = hit
    ? { found: true, record_id: hit.record_id, status: hit.status, last_contacted_days_ago: hit.last_contacted_days_ago, do_not_contact: hit.do_not_contact,
        label: "SIMULATED CRM RECORD" }
    : { found: false, label: "SIMULATED CRM LOOKUP - no match. INTEGRATION POINT: replace with Salesforce SOQL lookup or MCP_CRM_TOOL_REQUIRED" };
  g.crm_action = hit ? "UPDATE_EXISTING" : "CREATE_NEW";
  g.comms_suppression_reasons = [];
  if (hit && hit.do_not_contact) g.comms_suppression_reasons.push("DO_NOT_CONTACT");
  if (hit && !hit.do_not_contact && hit.last_contacted_days_ago < minDays) g.comms_suppression_reasons.push("RECENTLY_CONTACTED");
  g.raw_applications_in_run = rawCount;
  return { json: g };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const PATTERNS = CONFIG.protected_patterns.map(function(p){ return { label: p.label, source: p.pattern }; });

function esc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  let text = String(j.summary_text || "");
  const counts = {};
  let total = 0;

  const names = [j.first_name, j.last_name].join(" ").split(" ").filter(function(t){ return t && t.length >= 3; });
  names.forEach(function(n){
    text = text.replace(new RegExp("\\b" + esc(n) + "\\b", "gi"), function(){ total++; counts.name = (counts.name || 0) + 1; return "[CANDIDATE]"; });
  });
  PATTERNS.forEach(function(p){
    text = text.replace(new RegExp(p.source, "gi"), function(){ total++; counts[p.label] = (counts[p.label] || 0) + 1; return "[REDACTED]"; });
  });
  text = text.replace(/(\[REDACTED\]\s*){2,}/g, "[REDACTED] ").replace(/\s+/g, " ").trim();

  j.anonymised_summary = text;
  j.redaction_count = total;
  j.redaction_categories = counts;
  j.pii_policy_note = "Name, email, phone and protected-characteristic terms are removed from anything used for scoring or sent to an LLM.";
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const TAX = CONFIG.skills_taxonomy;
const termToCanon = {};
Object.keys(TAX).forEach(function(c){ termToCanon[c.toLowerCase()] = c; TAX[c].forEach(function(s){ termToCanon[s.toLowerCase()] = c; }); });
function esc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
const scanners = Object.keys(termToCanon).filter(function(t){ return t.length >= 2; }).map(function(t){
  return { canon: termToCanon[t], re: new RegExp("(^|[^a-z0-9])" + esc(t) + "($|[^a-z0-9])", "i") };
});

function seniorityFrom(title, years){
  const t = String(title || "").toLowerCase();
  if (/\b(lead|principal|head|director|staff|architect)\b/.test(t)) return { level: 4, source: "title" };
  if (/\b(senior|sr)\b/.test(t)) return { level: 3, source: "title" };
  if (/\b(junior|jr|graduate|trainee|entry|intern)\b/.test(t)) return { level: 1, source: "title" };
  if (years === null) return { level: 2, source: "default (experience missing)" };
  if (years >= 12) return { level: 4, source: "years" };
  if (years >= 6) return { level: 3, source: "years" };
  if (years >= 2) return { level: 2, source: "years" };
  return { level: 1, source: "years" };
}
const LABELS = { 1: "Junior", 2: "Mid-level", 3: "Senior", 4: "Lead / Principal" };

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };

  const found = {};
  const unrec = [];
  String(j.skills_raw || "").split(/[,;|\n]+/).forEach(function(tok){
    const k = tok.trim().toLowerCase();
    if (!k) return;
    if (termToCanon[k]) found[termToCanon[k]] = true; else unrec.push(tok.trim());
  });
  const hay = " " + String(j.anonymised_summary || "") + " " + String(j.current_title || "") + " ";
  scanners.forEach(function(s){ if (s.re.test(hay)) found[s.canon] = true; });
  const skills = Object.keys(found).sort();

  const titleL = String(j.current_title || "").toLowerCase();
  let best = "Unclassified", bestScore = 0;
  const scores = {};
  Object.keys(CONFIG.functions).forEach(function(fn){
    const f = CONFIG.functions[fn];
    let s = 0;
    f.title.forEach(function(k){ if (titleL.indexOf(k) !== -1) s += 3; });
    f.skills.forEach(function(k){ if (found[k]) s += 1; });
    scores[fn] = s;
    if (s > bestScore) { bestScore = s; best = fn; }
  });
  if (bestScore < 2) best = "Unclassified";

  const sen = seniorityFrom(j.current_title, j.years_experience);
  const region = CONFIG.regions[String(j.location || "").toLowerCase()] || "Unmapped region";

  j.skills = skills;
  j.skills_unrecognised = unrec;
  j.function = best;
  j.function_scores = scores;
  j.seniority_level = sen.level;
  j.seniority_label = LABELS[sen.level];
  j.seniority_source = sen.source;
  j.region = region;
  if (best === "Unclassified") j.review_reasons = (j.review_reasons || []).concat(["FUNCTION_UNCLASSIFIED"]);
  if (!skills.length) j.review_reasons = (j.review_reasons || []).concat(["NO_RECOGNISED_SKILLS"]);
  if (j.review_reasons.length) j.status = "REQUIRES_REVIEW";
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const W = CONFIG.scoring_weights;
const JOBS = CONFIG.mode === "LIVE" ? CONFIG.live_jobs : CONFIG.demo_jobs;

function r1(n){ return Math.round(n * 10) / 10; }
function arr(g){ return Array.isArray(g) ? g : [g]; }
function label(g){ return arr(g).join(" OR "); }
function related(a, b){
  return (CONFIG.related_functions || []).some(function(p){ return (p[0] === a && p[1] === b) || (p[0] === b && p[1] === a); });
}
function tierFor(score){
  for (const t of CONFIG.tiers) { if (score >= t.min) return t; }
  return CONFIG.tiers[CONFIG.tiers.length - 1];
}

function scoreJob(j, job){
  const have = {};
  (j.skills || []).forEach(function(s){ have[s] = true; });
  const flags = [];

  const mustMet = [], mustUnmet = [];
  (job.must_have || []).forEach(function(g){
    const hit = arr(g).filter(function(x){ return have[x]; });
    if (hit.length) mustMet.push(hit[0]); else mustUnmet.push(label(g));
  });
  const mustTotal = (job.must_have || []).length;
  const coverage = mustTotal ? mustMet.length / mustTotal : 1;
  const niceMet = (job.nice_to_have || []).filter(function(s){ return have[s]; });
  const niceCov = (job.nice_to_have || []).length ? niceMet.length / job.nice_to_have.length : 0;

  const diff = j.seniority_level - job.target_seniority;
  let sen = 0;
  if (diff === 0) sen = W.seniority_fit;
  else if (diff === 1) sen = W.seniority_fit * 0.8;
  else if (diff >= 2) { sen = W.seniority_fit * 0.4; flags.push("OVERQUALIFIED_FOR_LEVEL"); }
  else if (diff === -1) { sen = W.seniority_fit * 0.45; flags.push("BELOW_TARGET_SENIORITY"); }
  else { sen = 0; flags.push("BELOW_TARGET_SENIORITY"); }

  let fn = 0;
  if (j.function === job.function) fn = W.function_fit;
  else if (related(j.function, job.function)) fn = W.function_fit * 0.4;

  let loc = 0, locNote = "";
  if (job.work_mode === "remote") { loc = W.location_workmode; locNote = "remote role"; }
  else if (j.region === job.region) { loc = W.location_workmode; locNote = "same region"; }
  else if (j.relocate) { loc = W.location_workmode * 0.5; locNote = "open to relocate"; }
  else { loc = 0; locNote = "different region, not open to relocate"; flags.push("LOCATION_MISMATCH"); }

  let sal = 0;
  if (j.desired_salary === null) { sal = W.salary_alignment * 0.5; flags.push("SALARY_EXPECTATION_MISSING"); }
  else if (j.desired_salary <= job.salary_max) sal = W.salary_alignment;
  else if (j.desired_salary <= job.salary_max * 1.10) { sal = W.salary_alignment * 0.5; flags.push("SALARY_SLIGHTLY_ABOVE_BAND"); }
  else { sal = 0; flags.push("SALARY_ABOVE_BAND"); }

  let av = 0;
  if (j.notice_period_weeks === null) av = W.availability * 0.4;
  else if (j.notice_period_weeks <= 4) av = W.availability;
  else if (j.notice_period_weeks <= 8) av = W.availability * 0.6;
  else { av = W.availability * 0.2; flags.push("LONG_NOTICE_PERIOD"); }

  const b = {
    must_have_skills: r1(W.must_have_skills * coverage),
    nice_to_have_skills: r1(W.nice_to_have_skills * niceCov),
    seniority_fit: r1(sen), function_fit: r1(fn), location_workmode: r1(loc), salary_alignment: r1(sal), availability: r1(av)
  };
  let total = Object.keys(b).reduce(function(a, k){ return a + b[k]; }, 0);
  if (coverage < CONFIG.must_have_gate.min_coverage) {
    total = Math.min(total, CONFIG.must_have_gate.score_cap);
    flags.push("MUST_HAVE_GATE_APPLIED");
  }
  const score = Math.round(Math.max(0, Math.min(100, total)));
  return { job_id: job.job_id, job_title: job.title, function: job.function, score: score, breakdown: b, must_met: mustMet, must_unmet: mustUnmet,
    must_total: mustTotal, nice_met: niceMet, location_note: locNote, flags: flags, salary_band: [job.salary_min, job.salary_max], job_region: job.region, work_mode: job.work_mode };
}

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const all = JOBS.map(function(job){ return scoreJob(j, job); }).sort(function(a, b){ return b.score - a.score; });
  const best = all[0];
  j.job_scores = all;
  j.best_match = best;
  j.best_job_id = best ? best.job_id : "";
  j.match_score = best ? best.score : 0;
  j.score_tier = tierFor(j.match_score).tier;
  j.alternates = all.slice(1, 3).filter(function(a){ return a.score >= CONFIG.alternate_min_score; }).map(function(a){ return { job_id: a.job_id, job_title: a.job_title, score: a.score }; });
  j.score_formula = "must_have(40) + nice_to_have(10) + seniority(15) + function(10) + location/work-mode(10) + salary(10) + availability(5); must-have gate caps score at " + CONFIG.must_have_gate.score_cap + " when coverage < " + CONFIG.must_have_gate.min_coverage;
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const DISP = CONFIG.skill_display || {};
function disp(s){
  if (DISP[s]) return DISP[s];
  return String(s).split(" ").map(function(w){ return w.charAt(0).toUpperCase() + w.slice(1); }).join(" ");
}
function gbp(n){ return "GBP " + Number(n).toLocaleString("en-GB"); }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const b = j.best_match;
  const tier = CONFIG.tiers.filter(function(t){ return t.tier === j.score_tier; })[0];

  const strengths = [];
  if (b.must_met.length) strengths.push("FACT: Profile evidences " + b.must_met.map(disp).join(", ") + " (" + b.must_met.length + " of " + b.must_total + " must-have skills for " + b.job_title + ").");
  if (b.nice_met.length) strengths.push("FACT: Also lists nice-to-have skills: " + b.nice_met.map(disp).join(", ") + ".");
  if (j.years_experience !== null) strengths.push("FACT: " + j.years_experience + " years of experience stated; current title as entered: " + (j.current_title || "not stated") + ".");
  strengths.push("FACT: Profile classified as " + j.function + ", " + j.seniority_label + " level (source: " + j.seniority_source + ").");

  const gaps = b.must_unmet.map(function(g){ return "Not evidenced in profile: " + g + " (must-have) - verify on call. Absence from a CV is not proof of absence."; });

  const flags = b.flags.slice();
  const q = [];
  b.must_unmet.slice(0, 2).forEach(function(g){ q.push("Can you describe your hands-on experience with " + g + " in a production setting?"); });
  if (flags.indexOf("SALARY_ABOVE_BAND") !== -1 || flags.indexOf("SALARY_SLIGHTLY_ABOVE_BAND") !== -1) q.push("The band for this role is " + gbp(b.salary_band[0]) + " to " + gbp(b.salary_band[1]) + ". How flexible are your expectations?");
  if (flags.indexOf("LONG_NOTICE_PERIOD") !== -1) q.push("Is there any flexibility on your notice period?");
  if (flags.indexOf("LOCATION_MISMATCH") !== -1) q.push("This role is based in " + b.job_region + " (" + b.work_mode + "). Would that arrangement work for you?");
  if (flags.indexOf("OVERQUALIFIED_FOR_LEVEL") !== -1) q.push("This role is pitched at a slightly lower level than your background. What would make it attractive to you?");
  if (!q.length) q.push("What is prompting your interest in a move at this point?");

  const hyp = tier.tier === "A" ? "HYPOTHESIS: The profile may align closely with the brief; a short recruiter call is the quickest way to confirm depth."
    : tier.tier === "B" ? "HYPOTHESIS: The profile may align in part; the gaps listed could reflect CV wording rather than real gaps."
    : tier.tier === "C" ? "HYPOTHESIS: Not a close match for open roles today, but the background could suit future briefs in this function."
    : "HYPOTHESIS: No open role appears to be a close match on the evidence supplied.";

  let conf = 0.3;
  if ((j.skills || []).length >= 4) conf += 0.15;
  if (j.years_experience !== null) conf += 0.15;
  if ((j.anonymised_summary || "").length >= 40) conf += 0.15;
  if (j.current_title) conf += 0.1;
  if (j.email_valid) conf += 0.05;
  conf = Math.round(Math.min(0.9, conf) * 100) / 100;

  const analysis = {
    candidate_ref: j.candidate_ref, recommended_job_id: b.job_id, recommendation: tier.recommendation,
    fit_summary: "FACT: Deterministic match score " + j.match_score + "/100 for " + b.job_title + ". " + hyp,
    strengths: strengths, gaps: gaps, screening_questions: q.slice(0, 5), matched_skills: b.must_met.concat(b.nice_met), confidence: conf
  };
  j.analysis = analysis;
  j.analysis_source = "RULE_BASED_BASELINE";
  j.unmet_must = b.must_unmet;
  j.ai_payload = {
    candidate_ref: j.candidate_ref,
    anonymised_profile: { current_title: j.current_title, years_experience: j.years_experience, seniority: j.seniority_label, function: j.function,
      skills: j.skills, anonymised_summary: j.anonymised_summary, region: j.region, work_mode_pref: j.work_mode_pref,
      desired_salary_gbp: j.desired_salary, notice_period_weeks: j.notice_period_weeks },
    job: { job_id: b.job_id, title: b.job_title, function: b.function, region: b.job_region, work_mode: b.work_mode, salary_band_gbp: b.salary_band,
      must_have: b.must_met.concat(b.must_unmet), nice_to_have: b.nice_met },
    deterministic_match: { match_score: j.match_score, breakdown: b.breakdown, must_met: b.must_met, must_unmet: b.must_unmet, flags: b.flags },
    allowed_recommendations: Object.keys(CONFIG.recommendation_rank),
    baseline_analysis: analysis
  };
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const base = $('9. Deterministic Screening').all();
const incoming = $input.all();
const RANK = CONFIG.recommendation_rank;
const PATS = CONFIG.protected_patterns.filter(function(p){ return p.label !== "contact_details"; })
  .map(function(p){ return new RegExp(p.pattern, "i"); });

