function badge(t){ return '<span class="b b' + esc(t) + '">' + esc(t) + "</span>"; }
function kpi(v, l){ return '<div class="k"><b>' + esc(v) + "</b><span>" + esc(l) + "</span></div>"; }
const css = "body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;background:#f5f6f8;color:#1b1f24}.wrap{max-width:1200px;margin:0 auto;padding:24px}h1{font-size:22px;margin:0}.sub{color:#5a6472;font-size:13px}.banner{background:#fff7e0;border:1px solid #f0d98a;padding:8px 12px;border-radius:8px;font-size:12px;margin:12px 0}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}.k{background:#fff;border:1px solid #e3e6eb;border-radius:10px;padding:10px 12px}.k b{display:block;font-size:22px}.k span{font-size:11px;color:#5a6472;text-transform:uppercase;letter-spacing:.04em}table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #e3e6eb;font-size:12.5px}th,td{word-break:break-word;padding:7px 9px;border-bottom:1px solid #eef0f3;text-align:left;vertical-align:top}th{background:#fafbfc;font-size:11px;text-transform:uppercase;color:#5a6472}.b{display:inline-block;padding:1px 8px;border-radius:10px;font-weight:600;font-size:11px;color:#fff}.bA{background:#1a7f4b}.bB{background:#2b6cb0}.bC{background:#b7791f}.bD{background:#718096}.warn{color:#b42318;font-weight:600}.ok{color:#1a7f4b;font-weight:600}h2{font-size:15px;margin:22px 0 8px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:800px){.grid2{grid-template-columns:1fr}}.tw{overflow-x:auto}.small{font-size:11.5px;color:#5a6472}";

const h = [];
h.push('<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TalentFlow Engine</title><style>' + css + "</style></head><body><div class=\"wrap\">");
h.push("<h1>TalentFlow Engine - Recruitment Operations Dashboard</h1>");
h.push('<div class="sub">' + esc(CONFIG.agency) + " | mode " + esc(CONFIG.mode) + " | v" + esc(CONFIG.workflow_version) + " | " + esc(dashboard.generated_at) + "</div>");
h.push('<div class="banner"><b>' + esc(dashboard.data_label) + ".</b> All candidates, clients, recruiters and CRM records shown are synthetic or simulated. Recommendations only: a recruiter makes every decision and no message is sent automatically.</div>");
h.push('<div class="kpis">' + kpi(applications, "Applications received") + kpi(rows.length, "Unique candidates") + kpi(dupes, "Duplicates merged") + kpi(tierCount.A || 0, "Tier A fast-track") + kpi(tierCount.B || 0, "Tier B review") + kpi(slaRisk.length, "SLA at risk") + kpi(dashboard.requires_review, "Requires review") + kpi(redactions, "Protected terms redacted") + kpi(dashboard.estimated_manual_screening_hours_avoided + " h", "Est. hrs avoided (this run)*") + kpi(avg, "Avg match score") + "</div>");
h.push('<div class="small">*' + esc(dashboard.estimate_note) + " At 100 applications that is about " + dashboard.estimated_hours_avoided_per_100_applications + " recruiter hours.</div>");

h.push("<h2>Recruiter worklist (highest priority first)</h2><div class=\"tw\"><table><tr><th>Cand.</th><th>Best match</th><th>Score</th><th>Tier</th><th>Matched skills</th><th>Verify on call</th><th>Recruiter</th><th>SLA</th><th>Comms</th><th>CRM</th><th>Status</th></tr>");
worklist.forEach(function(w){
  h.push("<tr><td><b>" + esc(w.Candidate) + '</b><br><span class="small">' + esc(w.Ref) + "</span></td><td>" + esc(w.Best_Job) + "</td><td><b>" + esc(w.Match_Score) + "</b></td><td>" + badge(w.Tier) + "</td><td>" + esc(w.Matched_Skills) + "</td><td>" + esc(w.Gaps_To_Verify || "-") + "</td><td>" + esc(w.Recruiter) + "</td><td>" + esc(w.SLA_Target) + (w.SLA_At_Risk ? '<br><span class="warn">AT RISK</span>' : "") + "</td><td>" + esc(String(w.Comms_Status).indexOf("SUPPRESSED") === 0 ? w.Comms_Status : "Draft ready (approval required)") + "</td><td>" + esc(w.CRM_Action) + "</td><td>" + (w.Status === "OK" ? '<span class="ok">OK</span>' : '<span class="warn">REVIEW</span><br><span class="small">' + esc(w.Review_Reasons) + "</span>") + "</td></tr>");
});
h.push("</table></div>");

h.push('<div class="grid2"><div><h2>Pipeline health by open job</h2><table><tr><th>Job</th><th>Strong (65+)</th><th>Target</th><th>Health</th></tr>');
pipeline.forEach(function(p){ h.push("<tr><td>" + esc(p.job_id + " " + p.title) + "</td><td>" + p.strong_candidates + "</td><td>" + p.target_shortlist + "</td><td>" + (p.health === "HEALTHY" ? '<span class="ok">HEALTHY</span>' : '<span class="warn">' + p.health + "</span>") + "</td></tr>"); });
h.push("</table><div class=\"small\">Jobs below target get a Clay sourcing brief (" + sourcing.length + " generated).</div></div>");
h.push("<div><h2>Recruiter workload</h2><table><tr><th>Recruiter</th><th>A</th><th>B</th><th>C</th><th>Total</th></tr>");
Object.keys(load).forEach(function(k){ h.push("<tr><td>" + esc(k) + "</td><td>" + load[k].A + "</td><td>" + load[k].B + "</td><td>" + load[k].C + "</td><td>" + load[k].total + "</td></tr>"); });
h.push("</table></div></div>");

h.push('<div class="grid2"><div><h2>SLA at risk</h2><table><tr><th>Candidate</th><th>Job</th><th>Tier</th><th>Hours waiting</th></tr>');
if (!slaRisk.length) h.push('<tr><td colspan="4">None</td></tr>');
slaRisk.forEach(function(s){ h.push("<tr><td>" + esc(s.name) + "</td><td>" + esc(s.job) + "</td><td>" + badge(s.tier) + '</td><td class="warn">' + esc(s.hours_since_application) + "</td></tr>"); });
h.push("</table></div><div><h2>Data quality and skills insight</h2><table><tr><th>Issue</th><th>Count</th></tr>");
Object.keys(reasonTally).forEach(function(k){ h.push("<tr><td>" + esc(k) + "</td><td>" + reasonTally[k] + "</td></tr>"); });
h.push("</table><div class=\"small\">Top unmet must-haves: " + esc(top(gapCount, 5).map(function(x){ return x[0] + " (" + x[1] + ")"; }).join(", ") || "none") + "<br>Unrecognised skills to add to taxonomy: " + esc(top(unrec, 8).map(function(x){ return x[0]; }).join(", ") || "none") + "</div></div></div>");
h.push('<div class="small" style="margin-top:22px">' + esc(dashboard.measurement_note) + "</div></div></body></html>");

return [{ json: { dashboard: dashboard, worklist: worklist, salesforce_flow_blueprints: CONFIG.salesforce_flow_blueprints,
  crm_payloads: rows.map(function(r){ return { contact: r.salesforce_contact, candidate_match: r.salesforce_candidate_match, airtable: r.airtable_record }; }),
  html_report: h.join("") } }];
